    'EMPLOYEE',
    'EMP_AUTH',
    'EMP_POSITION',
    'EVALUATION_AI_REPORT',
    'EVALUATION_PERIOD',
    'HR_AI_CHAT_LOG',
    'HR_PLCY_CHUNK',
    'HR_PLCY_DOC',
    'HTE_APPR_AUTO_DELEGATION',
    'HTE_APPR_FORM_DELEGATION_CONFIG',
    'LEAVE_BALANCE',
    'LEAVE_GRANT',
    'LEAVE_REQUEST',
    'LOGIN_HISTORY',
    'NOTICE',
    'PERFORMANCE_EVALUATION',
    'PROJECT',
