--------------------------------------------------------
--  DDL for Procedure SP_GEN_COMPANY_DUMMY
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "SBERP"."SP_GEN_COMPANY_DUMMY" (p_count IN NUMBER) IS
  TYPE t_str_arr IS TABLE OF VARCHAR2(50);

  v_surname  t_str_arr := t_str_arr('김','이','박','최','정','강','조','윤','장','임','한','오','서','신','권');
  v_given    t_str_arr := t_str_arr('민준','서연','도윤','지우','하윤','예준','수아','시우','지호','유나','현우','소율','준서','채원','민재');
  v_name_pre t_str_arr := t_str_arr('스프링','한빛','미래','대한','우리','한국','조은','하늘','별','푸른','그린','블루','스마트','넥스트','골든');
  v_name_suf t_str_arr := t_str_arr('브리즈','전자','물류','시스템','테크','솔루션','네트웍스','바이오','에너지','푸드','케미칼','모터스','인더스트리','파트너스','글로벌');
  v_tel_area t_str_arr := t_str_arr('02','031','032','051','053','062','042','052','064');

  v_digits9  VARCHAR2(9);
  v_check    NUMBER;
  v_biz_no   VARCHAR2(15);
  v_com_name VARCHAR2(100);
  v_com_ceo  VARCHAR2(50);
  v_com_tel  VARCHAR2(30);
  v_grp_code VARCHAR2(10);
  v_ind_code VARCHAR2(10);
BEGIN
  FOR i IN 1..p_count LOOP

    -- 사업자등록번호: 순번 기반 9자리(중복없음) + 체크디지트 1자리
    v_digits9 := LPAD(TO_CHAR(100000000 + seq_biz_no_gen.NEXTVAL), 9, '0');
    v_check   := fn_calc_biz_check_digit(v_digits9);
    v_biz_no  := SUBSTR(v_digits9,1,3) || '-' || SUBSTR(v_digits9,4,2) || '-'
                 || SUBSTR(v_digits9,6,4) || TO_CHAR(v_check);

    -- 업종: industry_code 마스터에서 랜덤 추출 (O공공행정/T가구내고용/U국제기관 제외)
    SELECT industry_grp_code, industry_code
      INTO v_grp_code, v_ind_code
      FROM (
        SELECT industry_grp_code, industry_code
          FROM industry_code
         WHERE industry_grp_code NOT IN ('O','T','U')
         ORDER BY DBMS_RANDOM.VALUE
      )
     WHERE ROWNUM = 1;

    -- 회사명 / 대표자명 / 전화번호 랜덤 조합
    v_com_name := '(주)' || v_name_pre(TRUNC(DBMS_RANDOM.VALUE(1, v_name_pre.COUNT+1)))
                          || v_name_suf(TRUNC(DBMS_RANDOM.VALUE(1, v_name_suf.COUNT+1)));
    v_com_ceo  := v_surname(TRUNC(DBMS_RANDOM.VALUE(1, v_surname.COUNT+1)))
                          || v_given(TRUNC(DBMS_RANDOM.VALUE(1, v_given.COUNT+1)));
    v_com_tel  := v_tel_area(TRUNC(DBMS_RANDOM.VALUE(1, v_tel_area.COUNT+1))) || '-'
                          || LPAD(TRUNC(DBMS_RANDOM.VALUE(200,999)),3,'0') || '-'
                          || LPAD(TRUNC(DBMS_RANDOM.VALUE(1000,9999)),4,'0');

    -- NULL 최소화: com_tel / com_logo 100% 채움 (기본 로고 경로 지정)
    VALUES (v_grp_code, v_ind_code, v_com_name, v_com_ceo, v_biz_no, v_com_tel,
            '/images/company/default_logo.png');

  END LOOP;

