/
--------------------------------------------------------
--  DDL for Procedure SP_GEN_DEPARTMENT_TREE
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "SBERP"."SP_GEN_DEPARTMENT_TREE" (
  p_com_id    IN NUMBER,
  p_max_depth IN NUMBER   -- 이 회사의 최대 부서 계층 깊이 (2~5)
) IS
  TYPE t_str_arr IS TABLE OF VARCHAR2(50);

  -- 레벨별 부서명 후보 풀
  v_lv2 t_str_arr := t_str_arr('경영관리본부','영업본부','기술본부','생산본부','마케팅본부','고객지원본부');
  v_lv3 t_str_arr := t_str_arr('인사팀','총무팀','개발팀','QA팀','영업1팀','영업2팀','기획팀','디자인팀','구매팀','물류팀');
  v_lv4 t_str_arr := t_str_arr('프론트엔드파트','백엔드파트','인프라파트','데이터파트','UX파트','국내영업파트','해외영업파트');
  v_lv5 t_str_arr := t_str_arr('A셀','B셀','C셀','1파트','2파트');

  v_local_seq NUMBER := 0;  -- 회사별 dept_code 로컬 시퀀스 (com_id+dept_code UNIQUE 보장용)
  v_root_id   NUMBER;

  -- 재귀적으로 자식 부서를 생성하는 내부 프로시저
  PROCEDURE build_children(p_parent_id IN NUMBER, p_cur_depth IN NUMBER) IS
    v_pool      t_str_arr;
    v_child_cnt NUMBER;
    v_dept_id   NUMBER;
    v_name      VARCHAR2(100);
    v_code      VARCHAR2(100);
  BEGIN
    IF p_cur_depth > p_max_depth THEN
      RETURN;
    END IF;

    CASE p_cur_depth
      WHEN 2 THEN v_pool := v_lv2;
      WHEN 3 THEN v_pool := v_lv3;
      WHEN 4 THEN v_pool := v_lv4;
      WHEN 5 THEN v_pool := v_lv5;
      ELSE        v_pool := v_lv3;
    END CASE;

    v_child_cnt := TRUNC(DBMS_RANDOM.VALUE(2, 5));  -- 부서당 자식 2~4개

    FOR i IN 1..v_child_cnt LOOP
      v_local_seq := v_local_seq + 1;
      v_name := v_pool(TRUNC(DBMS_RANDOM.VALUE(1, v_pool.COUNT + 1)));
      v_code := 'D' || LPAD(v_local_seq, 4, '0');

      VALUES (p_com_id, p_parent_id, v_name, v_code, p_cur_depth, i, NULL)
      RETURNING dept_id INTO v_dept_id;

      -- 다음 레벨로 더 뻗을지 확률적으로 결정 (트리가 무한정 안 커지게)
      IF DBMS_RANDOM.VALUE(0,1) < 0.7 THEN
        build_children(v_dept_id, p_cur_depth + 1);
      END IF;
    END LOOP;
  END build_children;

BEGIN
  -- 루트(본사) 부서 생성 — parent_id는 정상적인 NULL
  v_local_seq := v_local_seq + 1;
  VALUES (p_com_id, NULL, '본사', 'HQ', 1, 1, NULL)
  RETURNING dept_id INTO v_root_id;

  build_children(v_root_id, 2);
END sp_gen_department_tree;

/
--------------------------------------------------------
--  DDL for Procedure SP_GEN_EMPLOYEE_DUMMY
--------------------------------------------------------
set define off;

  CREATE OR REPLACE EDITIONABLE PROCEDURE "SBERP"."SP_GEN_EMPLOYEE_DUMMY" (p_count IN NUMBER) IS
  TYPE t_num_tab IS TABLE OF NUMBER INDEX BY VARCHAR2(50);
  v_local_no  t_num_tab;

  TYPE t_str_arr IS TABLE OF VARCHAR2(50);
  v_surname t_str_arr := t_str_arr('김','이','박','최','정','강','조','윤','장','임','한','오','서','신','권');
  v_given   t_str_arr := t_str_arr('민준','서연','도윤','지우','하윤','예준','수아','시우','지호','유나','현우','소율','준서','채원','민재');

  v_com_id   NUMBER;
  v_dept_id  NUMBER;
  v_pos_id   NUMBER;
  v_key      VARCHAR2(50);
  v_no       NUMBER;
  v_emp_no   VARCHAR2(20);
  v_name     VARCHAR2(50);
  v_email    VARCHAR2(100);
  v_mobile   VARCHAR2(20);
  v_hire     DATE;
  v_status   VARCHAR2(10);
  v_rand     NUMBER;

  v_pass CONSTANT VARCHAR2(500) := '$2a$10$N9qo8uLOickgx2ZMRZoMye.IjSQA0VwGPcOt5EbHqHOFDVLfjRJeG';
BEGIN
  FOR i IN 1..p_count LOOP

    -- 회사 랜덤 선택
    SELECT com_id INTO v_com_id
      FROM (SELECT com_id FROM company ORDER BY DBMS_RANDOM.VALUE)
     WHERE ROWNUM = 1;
    v_key := TO_CHAR(v_com_id);

    -- 해당 회사의 부서/직급 중에서만 랜덤 선택 (FK 정합성)
    SELECT dept_id INTO v_dept_id
      FROM (SELECT dept_id FROM department WHERE com_id = v_com_id ORDER BY DBMS_RANDOM.VALUE)
     WHERE ROWNUM = 1;

    SELECT pos_id INTO v_pos_id
      FROM (SELECT pos_id FROM emp_position WHERE com_id = v_com_id ORDER BY DBMS_RANDOM.VALUE)
     WHERE ROWNUM = 1;

    -- 사번: 회사별 로컬 번호 (최초 1회 기존 최대값 조회 후 이후는 메모리에서 증가)
    IF NOT v_local_no.EXISTS(v_key) THEN
      SELECT NVL(MAX(TO_NUMBER(SUBSTR(emp_no, 5))), 0) INTO v_no
        FROM employee WHERE com_id = v_com_id;
      v_local_no(v_key) := v_no;
    END IF;
    v_local_no(v_key) := v_local_no(v_key) + 1;
    v_emp_no := 'EMP-' || LPAD(v_local_no(v_key), 4, '0');

    v_name  := v_surname(TRUNC(DBMS_RANDOM.VALUE(1, v_surname.COUNT + 1)))
            || v_given(TRUNC(DBMS_RANDOM.VALUE(1, v_given.COUNT + 1)));

    -- 이메일: com_id+로컬번호 조합으로 전역 유일성 보장
    v_email := 'emp' || v_com_id || '_' || v_local_no(v_key) || '@dummy-sberp.com';

    v_mobile := '010-' || LPAD(TRUNC(DBMS_RANDOM.VALUE(1000,9999)),4,'0')
                        || '-' || LPAD(TRUNC(DBMS_RANDOM.VALUE(1000,9999)),4,'0');

    v_hire := TRUNC(SYSDATE) - TRUNC(DBMS_RANDOM.VALUE(30, 3650));  -- 최근 약 10년 이내 랜덤 입사일

    -- 재직 상태 분포: 재직 90%, 휴직 5%, 퇴직 5%
    v_rand := DBMS_RANDOM.VALUE(0,1);
    v_status := CASE WHEN v_rand < 0.90 THEN '재직'
                      WHEN v_rand < 0.95 THEN '휴직'
                      ELSE '퇴직' END;

      emp_no, emp_name, emp_pass, emp_email, emp_mobile,
      emp_status, hire_date, com_id, pos_id, dept_id
    ) VALUES (
      v_emp_no, v_name, v_pass, v_email, v_mobile,
      v_status, v_hire, v_com_id, v_pos_id, v_dept_id
    );

  END LOOP;

  COMMIT;
END;

