--------------------------------------------------------
--  DDL for Function FN_CALC_BIZ_CHECK_DIGIT
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "SBERP"."FN_CALC_BIZ_CHECK_DIGIT" (p_digits9 IN VARCHAR2) RETURN NUMBER IS
  v_mul  SYS.ODCINUMBERLIST := SYS.ODCINUMBERLIST(1,3,7,1,3,7,1,3,5);
  v_sum  NUMBER := 0;
  v_d9   NUMBER;
BEGIN
  FOR i IN 1..9 LOOP
    v_sum := v_sum + TO_NUMBER(SUBSTR(p_digits9, i, 1)) * v_mul(i);
  END LOOP;
  v_d9  := TO_NUMBER(SUBSTR(p_digits9, 9, 1));
  v_sum := v_sum + TRUNC((v_d9 * 5) / 10);
  RETURN MOD(10 - MOD(v_sum, 10), 10);
END;

/
--------------------------------------------------------
--  DDL for Function FN_CHECK_BIZ_NO_STATUS
--------------------------------------------------------

  CREATE OR REPLACE EDITIONABLE FUNCTION "SBERP"."FN_CHECK_BIZ_NO_STATUS" (
  p_biz_no     IN VARCHAR2,   -- 하이픈 없는 10자리 (예: 1111111111)
  p_service_key IN VARCHAR2   -- data.go.kr 발급 서비스키 (URL-encoded)
) RETURN VARCHAR2 IS
  v_req        UTL_HTTP.REQ;
  v_resp       UTL_HTTP.RESP;
  v_url        VARCHAR2(500);
  v_body       CLOB;
  v_buffer     VARCHAR2(32767);
  v_status     VARCHAR2(50);
BEGIN
  v_url := 'https://api.odcloud.kr/api/nts-businessman/v1/status?serviceKey=' || p_service_key;

  v_req := UTL_HTTP.BEGIN_REQUEST(v_url, 'POST', 'HTTP/1.1');
  UTL_HTTP.SET_HEADER(v_req, 'Content-Type', 'application/json');
  UTL_HTTP.SET_HEADER(v_req, 'Accept', 'application/json');

  v_body := '{"b_no":["' || p_biz_no || '"]}';
  UTL_HTTP.SET_HEADER(v_req, 'Content-Length', LENGTHB(v_body));
  UTL_HTTP.WRITE_TEXT(v_req, v_body);

  v_resp := UTL_HTTP.GET_RESPONSE(v_req);

  BEGIN
    LOOP
      UTL_HTTP.READ_LINE(v_resp, v_buffer, TRUE);
      v_status := v_status || v_buffer;
    END LOOP;
  EXCEPTION
    WHEN UTL_HTTP.END_OF_BODY THEN
      UTL_HTTP.END_RESPONSE(v_resp);
  END;

  -- v_status는 원본 JSON 문자열. 필요한 값(b_stt, tax_type 등)은
  -- JSON_TABLE(v_status, '$.data[0]' COLUMNS (...)) 로 파싱해서 사용
  RETURN v_status;
END fn_check_biz_no_status;

